func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket rate limiter.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New creates a TokenBucket with the given capacity (max tokens) and
// refill rate (tokens per second). The clock must not be nil.
func New(capacity int, rate float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	return &TokenBucket{
		capacity: float64(capacity),
		rate:     rate,
		tokens:   float64(capacity),
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// NewDefault creates a TokenBucket using the system clock.
func NewDefault(capacity int, rate float64) (*TokenBucket, error) {
	return New(capacity, rate, realClock{})
}

// AllowN reports whether n tokens can be consumed right now, consuming
// them if so. It returns false for negative n.
func (b *TokenBucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if float64(n) > b.tokens {
		return false
	}
	b.tokens -= float64(n)
	return true
}

// Allow reports whether one token can be consumed right now.
func (b *TokenBucket) Allow() bool {
	return b.AllowN(1)
}

// Tokens returns the current estimated number of available tokens.
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	return b.tokens
}

func (b *TokenBucket) refillLocked() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.last = now
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
}
