func TestNewValidation(t *testing.T) {
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 10, 10, nil, true},
		{"zero capacity", 0, 10, newFakeClock(), true},
		{"negative capacity", -1, 10, newFakeClock(), true},
		{"zero rate", 10, 0, newFakeClock(), true},
		{"negative rate", 10, -1, newFakeClock(), true},
		{"valid", 10, 10, newFakeClock(), false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("New() error = %v, wantErr %v", err, tt.wantErr)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("New() returned nil bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name    string
		consume int
		advance time.Duration
		n       int
		want    bool
	}{
		{"zero tokens allowed", 0, 0, 0, true},
		{"negative rejected", 0, 0, -1, false},
		{"full capacity allowed", 0, 0, 10, true},
		{"above capacity rejected", 0, 0, 11, false},
		{"refill allows consumption", 10, 500 * time.Millisecond, 5, true},
		{"insufficient refill rejected", 10, 100 * time.Millisecond, 5, false},
		{"partial refill allowed", 10, 500 * time.Millisecond, 4, true},
		{"refill capped at capacity", 10, time.Hour, 10, true},
