func TestAllowNConcurrent(t *testing.T) {
	fc := newFakeClock()
	b, err := New(100, 100, fc)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var allowed atomic.Int32
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.AllowN(1) {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got > 100 {
		t.Errorf("allowed %d tokens, want <= 100", got)
	}
}
